function run_test() {
  for (const [contractID, iface] of tests) {
    dump(
      "trying to create component " +
        contractID +
        " with interface " +
        iface +
        "\n"
    );
    try {
      dump(Cc[contractID] + " " + Ci[iface] + "\n");
    } catch (e) {
      dump(e + "\n");
    }

    const comp = Cc[contractID].createInstance(Ci[iface]);
    Assert.ok(comp instanceof Ci[iface]);
  }
